const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const carWidth = 50;
const carHeight = 30;
const trackWidth = 400;
const trackHeight = 500;
const finishLineY = 50;
const aiCount = 3;
const maxSpeed = 5;
const acceleration = 0.1;
const deceleration = 0.05;
const turnSpeed = 0.05;

let playerCar = {
    x: canvas.width / 2 - carWidth / 2,
    y: canvas.height - carHeight - 50,
    speed: 0,
    angle: 0
};

let aiCars = Array.from({ length: aiCount }, () => ({
    x: Math.random() * (canvas.width - carWidth),
    y: Math.random() * (canvas.height - carHeight),
    speed: Math.random() * maxSpeed,
    angle: Math.random() * Math.PI * 2
}));

let lapCount = 0;
let lastLapTime = Date.now();

function drawCar(x, y, angle, color) {
    ctx.save();
    ctx.translate(x + carWidth / 2, y + carHeight / 2);
    ctx.rotate(angle);
    ctx.fillStyle = color;
    ctx.fillRect(-carWidth / 2, -carHeight / 2, carWidth, carHeight);
    ctx.restore();
}

function drawTrack() {
    ctx.fillStyle = 'green';
    ctx.fillRect(canvas.width / 2 - trackWidth / 2, canvas.height / 2 - trackHeight / 2, trackWidth, trackHeight);
    ctx.fillStyle = 'white';
    ctx.fillRect(canvas.width / 2 - trackWidth / 2 + 10, finishLineY, trackWidth - 20, 10);
}

function updatePlayerCar() {
    if (keys['ArrowUp']) playerCar.speed = Math.min(playerCar.speed + acceleration, maxSpeed);
    else if (keys['ArrowDown']) playerCar.speed = Math.max(playerCar.speed - deceleration, 0);
    else playerCar.speed *= 0.95;

    if (keys['ArrowLeft']) playerCar.angle -= turnSpeed;
    if (keys['ArrowRight']) playerCar.angle += turnSpeed;

    playerCar.x += playerCar.speed * Math.cos(playerCar.angle);
    playerCar.y += playerCar.speed * Math.sin(playerCar.angle);

    if (playerCar.y < finishLineY && playerCar.y + playerCar.speed * Math.sin(playerCar.angle) >= finishLineY) {
        lapCount++;
        lastLapTime = Date.now();
    }

    playerCar.x = Math.max(0, Math.min(canvas.width - carWidth, playerCar.x));
    playerCar.y = Math.max(0, Math.min(canvas.height - carHeight, playerCar.y));
}

function updateAiCars() {
    aiCars.forEach(car => {
        const targetAngle = Math.atan2(playerCar.y - car.y, playerCar.x - car.x);
        car.angle += (targetAngle - car.angle) * 0.05;

        car.speed = Math.min(car.speed + acceleration, maxSpeed);
        car.x += car.speed * Math.cos(car.angle);
        car.y += car.speed * Math.sin(car.angle);

        car.x = Math.max(0, Math.min(canvas.width - carWidth, car.x));
        car.y = Math.max(0, Math.min(canvas.height - carHeight, car.y));
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawTrack();
    drawCar(playerCar.x, playerCar.y, playerCar.angle, 'blue');
    aiCars.forEach((car, index) => drawCar(car.x, car.y, car.angle, `red`));
    ctx.fillStyle = 'black';
    ctx.fillText(`Lap: ${lapCount}`, 10, 20);
    ctx.fillText(`Time: ${(Date.now() - lastLapTime) / 1000}s`, 10, 40);
}

let keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop() {
    updatePlayerCar();
    updateAiCars();
    draw();
    requestAnimationFrame(gameLoop);
}

gameLoop();
