const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const jumpForce = -10;
const moveSpeed = 5;
const platformWidth = 100;
const platformHeight = 20;
const coinRadius = 5;

class Player {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 30;
        this.height = 50;
        this.velocityY = 0;
        this.jumpsLeft = 2;
    }

    update() {
        this.velocityY += gravity;
        this.y += this.velocityY;

        if (this.y + this.height > canvas.height) {
            this.y = canvas.height - this.height;
            this.velocityY = 0;
            this.jumpsLeft = 2;
        }
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    jump() {
        if (this.jumpsLeft > 0) {
            this.velocityY = jumpForce;
            this.jumpsLeft--;
        }
    }

    moveLeft() {
        this.x -= moveSpeed;
    }

    moveRight() {
        this.x += moveSpeed;
    }
}

class Platform {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = platformWidth;
        this.height = platformHeight;
    }

    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

class Coin {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.radius = coinRadius;
    }

    draw() {
        ctx.fillStyle = 'yellow';
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fill();
    }
}

const player = new Player(100, canvas.height - 100);
const platforms = [
    new Platform(100, canvas.height - 50),
    new Platform(300, canvas.height - 150),
    new Platform(500, canvas.height - 250)
];
const coins = [
    new Coin(200, canvas.height - 100),
    new Coin(400, canvas.height - 200),
    new Coin(600, canvas.height - 300)
];

function checkCollision(rect1, rect2) {
    return (
        rect1.x < rect2.x + rect2.width &&
        rect1.x + rect1.width > rect2.x &&
        rect1.y < rect2.y + rect2.height &&
        rect1.y + rect1.height > rect2.y
    );
}

function checkCoinCollision(player, coin) {
    const dx = player.x + player.width / 2 - coin.x;
    const dy = player.y + player.height / 2 - coin.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < player.width / 2 + coin.radius;
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    player.update();

    for (let platform of platforms) {
        platform.draw();
        if (checkCollision(player, platform)) {
            player.y = platform.y - player.height;
            player.velocityY = 0;
            player.jumpsLeft = 2;
        }
    }

    for (let i = coins.length - 1; i >= 0; i--) {
        const coin = coins[i];
        coin.draw();
        if (checkCoinCollision(player, coin)) {
            coins.splice(i, 1);
        }
    }

    player.draw();

    requestAnimationFrame(update);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') {
        player.moveLeft();
    } else if (e.key === 'ArrowRight') {
        player.moveRight();
    } else if (e.key === 'Space') {
        player.jump();
    }
});

update();
