const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const towerTypes = [
  { name: 'Basic', range: 100, damage: 10, color: 'blue' },
  { name: 'Advanced', range: 150, damage: 20, color: 'green' },
  { name: 'Elite', range: 200, damage: 30, color: 'red' }
];

let towers = [];
let enemies = [];
let path = [{ x: 50, y: 50 }, { x: 750, y: 50 }, { x: 750, y: 550 }, { x: 50, y: 550 }];
let waveCount = 0;
let score = 0;

function drawPath() {
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 5;
  for (let i = 0; i < path.length - 1; i++) {
    ctx.beginPath();
    ctx.moveTo(path[i].x, path[i].y);
    ctx.lineTo(path[i + 1].x, path[i + 1].y);
    ctx.stroke();
  }
}

function drawTowers() {
  towers.forEach(tower => {
    ctx.fillStyle = tower.color;
    ctx.beginPath();
    ctx.arc(tower.x, tower.y, 10, 0, Math.PI * 2);
    ctx.fill();
  });
}

function drawEnemies() {
  enemies.forEach(enemy => {
    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, 5, 0, Math.PI * 2);
    ctx.fill();
  });
}

function spawnWave() {
  waveCount++;
  const waveSize = waveCount * 5;
  for (let i = 0; i < waveSize; i++) {
    enemies.push({ x: path[0].x, y: path[0].y, speed: 1 + waveCount / 10 });
  }
}

function moveEnemies() {
  enemies.forEach((enemy, index) => {
    const target = path.find(p => p.x === enemy.x && p.y === enemy.y);
    if (target) {
      const next = path[path.indexOf(target) + 1];
      if (next) {
        enemy.x += (next.x - enemy.x) * enemy.speed;
        enemy.y += (next.y - enemy.y) * enemy.speed;
      } else {
        enemies.splice(index, 1);
        score -= 10;
      }
    }
  });
}

function attackEnemies() {
  towers.forEach(tower => {
    const inRange = enemies.filter(enemy => {
      const dx = enemy.x - tower.x;
      const dy = enemy.y - tower.y;
      return Math.sqrt(dx * dx + dy * dy) <= tower.range;
    });

    if (inRange.length > 0) {
      const target = inRange[0];
      target.health = (target.health || 100) - tower.damage;
      if (target.health <= 0) {
        enemies.splice(enemies.indexOf(target), 1);
        score += 10;
      }
    }
  });
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawPath();
  drawTowers();
  drawEnemies();
  drawScore();

  moveEnemies();
  attackEnemies();

  if (enemies.length === 0) {
    spawnWave();
  }

  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  towers.push({ x, y, type: towerTypes[Math.floor(Math.random() * towerTypes.length)] });
});

spawnWave();
gameLoop();
