const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const paddleWidth = 100;
const paddleHeight = 10;
const ballRadius = 10;
const brickRowCount = 5;
const brickColumnCount = 10;
const brickWidth = 75;
const brickHeight = 20;
const brickPadding = 10;
const brickOffsetTop = 30;
const brickOffsetLeft = 30;

let x = canvas.width / 2;
let y = canvas.height - 30;
let dx = 2;
let dy = -2;
let paddleX = (canvas.width - paddleWidth) / 2;
let rightPressed = false;
let leftPressed = false;
let score = 0;
let lives = 3;
let level = 1;
let powerUpActive = false;
let powerUpType = '';
let powerUpX = 0;
let powerUpY = 0;
let powerUpDX = 2;
let powerUpDY = 2;
let powerUpTimer = 0;
let balls = [{ x, y, dx, dy }];

const bricks = [];
for (let c = 0; c < brickColumnCount; c++) {
    bricks[c] = [];
    for (let r = 0; r < brickRowCount; r++) {
        bricks[c][r] = { x: 0, y: 0, status: 1 };
    }
}

document.addEventListener('keydown', keyDownHandler, false);
document.addEventListener('keyup', keyUpHandler, false);
document.addEventListener('mousemove', mouseMoveHandler, false);

function keyDownHandler(e) {
    if (e.key === 'Right' || e.key === 'ArrowRight') {
        rightPressed = true;
    } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
        leftPressed = true;
    }
}

function keyUpHandler(e) {
    if (e.key === 'Right' || e.key === 'ArrowRight') {
        rightPressed = false;
    } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
        leftPressed = false;
    }
}

function mouseMoveHandler(e) {
    const relativeX = e.clientX - canvas.offsetLeft;
    if (relativeX > 0 && relativeX < canvas.width) {
        paddleX = relativeX - paddleWidth / 2;
    }
}

function collisionDetection() {
    for (let c = 0; c < brickColumnCount; c++) {
        for (let r = 0; r < brickRowCount; r++) {
            const b = bricks[c][r];
            if (b.status === 1) {
                if (x > b.x && x < b.x + brickWidth && y > b.y && y < b.y + brickHeight) {
                    dy = -dy;
                    b.status = 0;
                    score++;
                    if (score % (brickRowCount * brickColumnCount) === 0) {
                        level++;
                        if (level > 3) {
                            alert('YOU WIN, CONGRATULATIONS!');
                            document.location.reload();
                        }
                        resetLevel();
                    }
                }
            }
        }
    }
}

function drawBall(x, y) {
    ctx.beginPath();
    ctx.arc(x, y, ballRadius, 0, Math.PI * 2);
    ctx.fillStyle = '#0095DD';
    ctx.fill();
    ctx.closePath();
}

function drawPaddle() {
    ctx.beginPath();
    ctx.rect(paddleX, canvas.height - paddleHeight, paddleWidth, paddleHeight);
    ctx.fillStyle = '#0095DD';
    ctx.fill();
    ctx.closePath();
}

function drawBricks() {
    for (let c = 0; c < brickColumnCount; c++) {
        for (let r = 0; r < brickRowCount; r++) {
            if (bricks[c][r].status === 1) {
                const brickX = (c * (brickWidth + brickPadding)) + brickOffsetLeft;
                const brickY = (r * (brickHeight + brickPadding)) + brickOffsetTop;
                bricks[c][r].x = brickX;
                bricks[c][r].y = brickY;
                ctx.beginPath();
                ctx.rect(brickX, brickY, brickWidth, brickHeight);
                ctx.fillStyle = '#0095DD';
                ctx.fill();
                ctx.closePath();
            }
        }
    }
}

function drawScore() {
    ctx.font = '16px Arial';
    ctx.fillStyle = '#0095DD';
    ctx.fillText(`Score: ${score}`, 8, 20);
}

function drawLives() {
    ctx.font = '16px Arial';
    ctx.fillStyle = '#0095DD';
    ctx.fillText(`Lives: ${lives}`, canvas.width - 65, 20);
}

function drawPowerUp() {
    if (powerUpActive) {
        ctx.beginPath();
        ctx.arc(powerUpX, powerUpY, ballRadius, 0, Math.PI * 2);
        ctx.fillStyle = 'gold';
        ctx.fill();
        ctx.closePath();
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBricks();
    for (const ball of balls) {
        drawBall(ball.x, ball.y);
    }
    drawPaddle();
    drawScore();
    drawLives();
    drawPowerUp();

    for (const ball of balls) {
        if (ball.x + ball.dx > canvas.width - ballRadius || ball.x + ball.dx < ballRadius) {
            ball.dx = -ball.dx;
        }
        if (ball.y + ball.dy < ballRadius) {
            ball.dy = -ball.dy;
        } else if (ball.y + ball.dy > canvas.height - ballRadius) {
            if (ball.x > paddleX && ball.x < paddleX + paddleWidth) {
                ball.dy = -ball.dy;
            } else {
                lives--;
                if (!lives) {
                    alert('GAME OVER');
                    document.location.reload();
                } else {
                    resetLevel();
                }
            }
        }

        ball.x += ball.dx;
        ball.y += ball.dy;
    }

    if (powerUpActive) {
        if (powerUpX + powerUpDX > canvas.width - ballRadius || powerUpX + powerUpDX < ballRadius) {
            powerUpDX = -powerUpDX;
        }
        if (powerUpY + powerUpDY > canvas.height - ballRadius || powerUpY + powerUpDY < ballRadius) {
            powerUpDY = -powerUpDY;
        }

        powerUpX += powerUpDX;
        powerUpY += powerUpDY;

        if (powerUpX > paddleX && powerUpX < paddleX + paddleWidth && powerUpY > canvas.height - paddleHeight - ballRadius && powerUpY < canvas.height - paddleHeight + ballRadius) {
            powerUpActive = false;
            applyPowerUp();
        }
    }

    collisionDetection();

    if (Math.random() < 0.01 && !powerUpActive) {
        powerUpActive = true;
        powerUpX = Math.random() * (canvas.width - ballRadius * 2) + ballRadius;
        powerUpY = Math.random() * (canvas.height - ballRadius * 2) + ballRadius;
        powerUpType = Math.random() > 0.5 ? 'multiball' : 'widepaddle';
    }

    requestAnimationFrame(draw);
}

function resetLevel() {
    x = canvas.width / 2;
    y = canvas.height - 30;
    dx = 2;
    dy = -2;
    paddleX = (canvas.width - paddleWidth) / 2;
    balls = [{ x, y, dx, dy }];
    powerUpActive = false;
    powerUpTimer = 0;
    for (let c = 0; c < brickColumnCount; c++) {
        for (let r = 0; r < brickRowCount; r++) {
            bricks[c][r].status = 1;
        }
    }
}

function applyPowerUp() {
    if (powerUpType === 'multiball') {
        const newBalls = [];
        for (const ball of balls) {
            newBalls.push({ x: ball.x, y: ball.y, dx: -ball.dx, dy: ball.dy });
        }
        balls = [...balls, ...newBalls];
    } else if (powerUpType === 'widepaddle') {
        paddleWidth *= 1.5;
        setTimeout(() => {
            paddleWidth /= 1.5;
        }, 10000);
    }
}

draw();
