const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const hook = {
    x: canvas.width / 2,
    y: canvas.height - 50,
    length: 150,
    angle: Math.PI / 4,
    speed: 0.05,
    isReeling: false
};

const fish = {
    x: Math.random() * canvas.width,
    y: 0,
    speed: 1 + Math.random() * 2,
    caught: false
};

let score = 0;

function drawHook() {
    ctx.beginPath();
    ctx.moveTo(hook.x, hook.y);
    ctx.lineTo(hook.x + hook.length * Math.cos(hook.angle), hook.y - hook.length * Math.sin(hook.angle));
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 3;
    ctx.stroke();
}

function drawFish() {
    ctx.beginPath();
    ctx.arc(fish.x, fish.y, 10, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
}

function update() {
    if (!fish.caught) {
        fish.y += fish.speed;
        if (fish.y > canvas.height) {
            fish.x = Math.random() * canvas.width;
            fish.y = 0;
            fish.speed = 1 + Math.random() * 2;
        }
    }

    if (hook.isReeling) {
        hook.length -= 2;
        if (hook.length <= 0) {
            hook.length = 0;
            hook.isReeling = false;
            if (Math.abs(fish.x - hook.x) < 20 && Math.abs(fish.y - hook.y) < 20) {
                fish.caught = true;
                score++;
            }
        }
    } else {
        hook.angle += hook.speed;
        if (hook.angle > Math.PI * 3 / 4 || hook.angle < Math.PI / 4) {
            hook.speed *= -1;
        }
    }
}

function drawScore() {
    ctx.font = '20px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawHook();
    drawFish();
    drawScore();
    update();
    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', () => {
    hook.isReeling = true;
});

gameLoop();
