class Inventory {
  constructor(cap){this.slots=new Map();this.capacity=cap;this.carry=0;}
  add(item,q=1){if(this.carry+item.weight*q>this.capacity)return false;this.carry+=item.weight*q;const e=this.slots.get(item.id);if(e)e.qty+=q;else this.slots.set(item.id,{item,qty:q});return true;}
  remove(id,q=1){const e=this.slots.get(id);if(!e||e.qty<q)return null;e.qty-=q;this.carry-=e.item.weight*q;if(e.qty===0)this.slots.delete(id);return e.item;}
  equip(id){const e=this.slots.get(id);if(!e||!e.item.equip)return null;this.active=e.item;return e.item;}
  unequip(){if(this.active)this.slots.get(this.active.id).qty+=1;const prev=this.active;this.active=null;return prev;}
  bonus(stat){return this.active?.equip[stat]||0;}
}
class Character { constructor(base,inv){this.base=base;this.inv=inv;} stat(name){return (this.base[name]||0)+this.inv.bonus(name);} }
const inv=new Inventory(50), hero=new Character({attack:5,defense:2},inv);
