class CombatSystem {
  constructor() { this.turn = 0; this.entities = []; }
  add(entity) { entity.combat = { hp: entity.hp, maxHp: entity.hp, ac: entity.ac, speed: entity.speed, status: [] }; this.entities.push(entity); }
  initiative() { return this.entities.slice().sort((a, b) => b.combat.speed - a.combat.speed); }
  attack(attacker, defender) {
    const roll = 1 + Math.floor(Math.random() * 20);
    let dmg = roll >= defender.combat.ac ? 1 + Math.floor(Math.random() * attacker.attack) : 0;
    if (attacker.status?.includes('bleed')) dmg *= 2;
    if (defender.combat.status.includes('armorUp')) dmg = Math.floor(dmg / 2);
    defender.combat.hp -= dmg;
    if (dmg > 0 && Math.random() < 0.2) this._maybeApplyStatus(defender, attacker.status?.[0]);
    return { roll, dmg };
  }
  _maybeApplyStatus(target, name) {
    if (!name || target.combat.status.includes(name)) return;
    if (Math.random() < 0.4) { target.combat.status.push(name); console.log(`${target.name} gains ${name}`); }
  }
  heal(entity, amount) { entity.combat.hp = Math.min(entity.combat.maxHp, entity.combat.hp + amount); }
  isAlive(entity) { return entity.combat.hp > 0; }
}

class Entity { constructor(name, hp, ac, speed, attack) { this.name = name; this.hp = hp; this.ac = ac; this.speed = speed; this.attack = attack; } }

const combat = new CombatSystem();
const hero = new Entity('Hero', 50, 16, 12, 8);
const foe = new Entity('Foe', 40, 14, 10, 6);
combat.add(hero);
combat.add(foe);

// Apply a status effect to the foe
hero.status = ['bleed'];

// Run a few turns
for (let i = 0; i < 3; i++) {
  for (const e of combat.initiative()) {
    if (!combat.isAlive(e)) continue;
    const target = e === hero ? foe : hero;
    if (combat.isAlive(target)) {
      const res = combat.attack(e, target);
      console.log(`${e.name} attacks ${target.name} for ${res.dmg}`);
    }
  }
