class Character {
  constructor(name, health, strength, defense) {
    this.name = name;
    this.health = health;
    this.strength = strength;
    this.defense = defense;
    this.personality = this.generatePersonality();
  }

  generatePersonality() {
    const traits = [
      "Brave", "Clever", "Kind", "Lazy", "Mysterious", "Optimistic", "Pessimistic", "Quick", "Reliable", "Stubborn"
    ];
    const randomIndex = Math.floor(Math.random() * traits.length);
    return traits[randomIndex];
  }

  takeDamage(amount) {
    const damageTaken = Math.max(0, amount - this.defense);
    this.health -= damageTaken;
    console.log(`${this.name} takes ${damageTaken} damage. Health: ${this.health}`);
  }

  attack(target) {
    const damageDealt = this.strength;
    target.takeDamage(damageDealt);
    console.log(`${this.name} attacks ${target.name} for ${damageDealt} damage.`);
  }

  describe() {
    console.log(`Character: ${this.name}, Health: ${this.health}, Strength: ${this.strength}, Defense: ${this.defense}, Personality: ${this.personality}`);
  }
}

